sql_query_template:
SELECT
    100.0 * COUNT_IF(
        {match_condition}
    ) / NULLIF(COUNT({column}), 0) AS metric_value,
    COUNT_IF({match_condition}) AS passed_count,
    COUNT_IF(NOT ({match_condition})) AS failed_count,
    COUNT({column}) AS total_count,
    COUNT({column}) AS applicable_count
FROM {table}
WHERE {column} IS NOT NULL

SELECT
    100.0 * COUNT_IF(
        {primary_key_column} IS NULL
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF(
        {primary_key_column} IS NOT NULL
    ) AS passed_count,
    COUNT_IF(
        {primary_key_column} IS NULL
    ) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

SELECT
    100.0 * ABS(
        COUNT(*) - {baseline_row_count}
    ) / NULLIF({baseline_row_count}, 0) AS metric_value,
    1 AS passed_count,
    0 AS failed_count,
    1 AS total_count,
    1 AS applicable_count
FROM {table}

SELECT
    100.0 * COUNT_IF(
        {arrival_timestamp_column} > {expected_arrival}
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF(
        {arrival_timestamp_column} <= {expected_arrival}
    ) AS passed_count,
    COUNT_IF(
        {arrival_timestamp_column} > {expected_arrival}
    ) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}
WHERE {arrival_timestamp_column} IS NOT NULL

SELECT
    100.0 * COUNT_IF(
        {primary_key_column} IS NULL
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF(
        {primary_key_column} IS NOT NULL
    ) AS passed_count,
    COUNT_IF(
        {primary_key_column} IS NULL
    ) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

SELECT
    100.0 * ABS(
        COUNT(*) - {baseline_row_count}
    ) / NULLIF({baseline_row_count}, 0) AS metric_value,
    1 AS passed_count,
    0 AS failed_count,
    1 AS total_count,
    1 AS applicable_count
FROM {table}

SELECT
    100.0 * COUNT_IF(
        {arrival_timestamp_column} > {expected_arrival}
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF(
        {arrival_timestamp_column} <= {expected_arrival}
    ) AS passed_count,
    COUNT_IF(
        {arrival_timestamp_column} > {expected_arrival}
    ) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}
WHERE {arrival_timestamp_column} IS NOT NULL

SELECT
    100.0 * COUNT_IF(
        {primary_key_column} IS NULL
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF(
        {primary_key_column} IS NOT NULL
    ) AS passed_count,
    COUNT_IF(
        {primary_key_column} IS NULL
    ) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

SELECT
    100.0 * ABS(
        COUNT(*) - {baseline_row_count}
    ) / NULLIF({baseline_row_count}, 0) AS metric_value,
    1 AS passed_count,
    0 AS failed_count,
    1 AS total_count,
    1 AS applicable_count
FROM {table}

SELECT
    100.0 * COUNT_IF(
        {arrival_timestamp_column} > {expected_arrival}
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF(
        {arrival_timestamp_column} <= {expected_arrival}
    ) AS passed_count,
    COUNT_IF(
        {arrival_timestamp_column} > {expected_arrival}
    ) AS failed_count,
    COUNT(*) AS total_count,
